        // 1. 解析配置信息
        BeanDefinition bd = getBeanDefinition(beanName);

        // 2. 创建对象实例
        Object instance = createInstance(bd);

        // 3. 注入依赖对象
        injectDependencies(instance, bd);

        // 4. 执行初始化
        initialize(instance, bd);

        return instance;
